    72	type SlotOccupant =
    73	  | { state: 'valid'; pid: number; token: string | null; meta: Record<string, unknown> }
    74	  | { state: 'corrupt'; identity: string }
    75	  | { state: 'missing' };
    76	
    77	function corruptSlotIdentity(file: string, raw: string): string {
    78	  try {
    79	    const stat = statSync(file);
    80	    return `${stat.dev}:${stat.ino}:${stat.size}:${stat.mtimeMs}:${raw}`;
    81	  } catch (error) {
    82	    return `unstatable:${(error as NodeJS.ErrnoException).code ?? 'unknown'}:${raw}`;
    83	  }
    84	}
    85	
    86	function ownString(value: Record<string, unknown>, key: string): string | null {
    87	  if (!Object.prototype.hasOwnProperty.call(value, key)) return null;
    88	  return typeof value[key] === 'string' ? value[key] as string : null;
    89	}
    90	
    91	function ownNumber(value: Record<string, unknown>, key: string): number | null {
    92	  if (!Object.prototype.hasOwnProperty.call(value, key)) return null;
    93	  return typeof value[key] === 'number' && Number.isInteger(value[key]) ? value[key] as number : null;
    94	}
    95	
    96	function readSlotOccupant(file: string): SlotOccupant {
    97	  let raw: string;
    98	  try {
    99	    raw = readFileSync(file, 'utf8');
   100	  } catch (error) {
   101	    return (error as NodeJS.ErrnoException).code === 'ENOENT'
   102	      ? { state: 'missing' }
   103	      : { state: 'corrupt', identity: corruptSlotIdentity(file, '') };
   104	  }
   105	  try {
   106	    const parsed = JSON.parse(raw) as unknown;
   107	    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
   108	      return { state: 'corrupt', identity: corruptSlotIdentity(file, raw) };
   109	    }
   110	    const meta = parsed as Record<string, unknown>;
   111	    const pid = ownNumber(meta, 'pid');
   112	    if (pid === null) return { state: 'corrupt', identity: corruptSlotIdentity(file, raw) };
   113	    return { state: 'valid', pid, token: ownString(meta, 'token'), meta };
   114	  } catch {
   115	    return { state: 'corrupt', identity: corruptSlotIdentity(file, raw) };
   116	  }
   117	}
   118	
   119	function sameSlotOccupant(left: SlotOccupant, right: SlotOccupant): boolean {
   120	  if (left.state !== right.state) return false;
   121	  if (left.state === 'valid' && right.state === 'valid') {
   122	    return left.pid === right.pid && left.token === right.token;
   123	  }
   124	  if (left.state === 'corrupt' && right.state === 'corrupt') {
   125	    return left.identity === right.identity;
   126	  }
   127	  return true;
   128	}
   129	
   130	function pidAlive(pid: number): boolean {
   131	  if (!Number.isInteger(pid) || pid <= 0) return false;
   132	  try {
   133	    process.kill(pid, 0);
   134	    return true;
   135	  } catch (error) {
   136	    return (error as NodeJS.ErrnoException).code === 'EPERM';
   137	  }
   138	}
   139	
   140	function processGroupAlive(pgid: number): boolean {
   141	  if (!Number.isInteger(pgid) || pgid <= 0 || process.platform === 'win32') return false;
   142	  try {
   143	    process.kill(-pgid, 0);
   144	    return true;
   145	  } catch (error) {
   146	    return (error as NodeJS.ErrnoException).code === 'EPERM';
   147	  }
   148	}
   149	
   150	function slotReclaimable(occupant: SlotOccupant, file: string, now: number, staleMs: number): boolean {
   151	  if (occupant.state === 'missing') return true;
   152	  if (occupant.state === 'valid') {
   153	    const isolated = occupant.meta.providerProcessGroupIsolated === true;
   154	    const providerPgid = ownNumber(occupant.meta, 'providerPgid');
   155	    // Once the admission has transferred to an isolated provider group, the
   156	    // group—not the supervising worker—is the capacity owner. A crashed worker
   157	    // may leave children alive, so reclaim only after the exact PGID disappears.
   158	    if (isolated && providerPgid !== null && processGroupAlive(providerPgid)) return false;
   159	    return !pidAlive(occupant.pid);
   160	  }
   161	  try {
   162	    const ageMs = now - statSync(file).mtimeMs;
   163	    return !Number.isFinite(ageMs) || ageMs > staleMs;
   164	  } catch {
   165	    // Fail closed: an existing slot we cannot stat still occupies capacity.
   166	    return false;
   167	  }
   168	}
