   240	function currentProcessStartTimeMs(): number {
   241	  return Math.floor(Date.now() - process.uptime() * 1_000);
   242	}
   243	
   244	function sameProcessStart(left: number | undefined, right: number | undefined): boolean {
   245	  if (left === undefined || right === undefined) return true;
   246	  return Math.abs(left - right) <= 2_000;
   247	}
