   249	// B-137a:F-124 — used at the classifyExistingLock wiring below, so NOT dead
   250	// code; the `export` was the only dead part (no importer anywhere in
   251	// packages/main/src or scripts). Narrowed to module-private.
   252	function classifyProviderRegistryLock(snapshot: ExistingMkdirLockSnapshot): ExistingMkdirLockState {
   253	  const holder = snapshot.holder;
   254	  if (!holder || holder.hostname !== hostname()) return 'unknown';
   255	  if (!Number.isInteger(holder.pid) || holder.pid <= 0) return 'unknown';
   256	  try {
   257	    process.kill(holder.pid, 0);
   258	  } catch (error) {
   259	    const code = (error as NodeJS.ErrnoException).code;
   260	    if (code === 'ESRCH') return 'stale';
   261	    if (code !== 'EPERM') return 'unknown';
   262	  }
   263	  if (
   264	    holder.pid === process.pid
   265	    && !sameProcessStart(holder.processStartTimeMs, currentProcessStartTimeMs())
   266	  ) return 'stale';
   267	  return 'active';
   268	}
