   270	function withProviderRegistryLock<T>(
   271	  dir: string,
   272	  fn: () => T,
   273	  timing: ProviderRegistryLockTiming = {},
   274	): T {
   275	  const lock = acquireMkdirLock(`${dir}.lock`, {
   276	    label: 'provider-process-registry',
   277	    deadlineMs: timing.deadlineMs ?? 30_000,
   278	    staleMs: timing.staleMs ?? 10_000,
   279	    pollMs: timing.pollMs ?? 10,
   280	    requireHolderToken: true,
   281	    classifyExistingLock: classifyProviderRegistryLock,
   282	    holderInfo: {
   283	      pid: process.pid,
   284	      hostname: hostname(),
   285	      command: 'provider-process-registry mutation',
   286	      acquiredAt: new Date().toISOString(),
   287	      lockId: randomUUID(),
   288	      processStartTimeMs: currentProcessStartTimeMs(),
   289	    },
   290	  });
   291	  try {
   292	    return fn();
   293	  } finally {
   294	    lock.release();
   295	  }
   296	}
