   298	export function scanLiveProviderProcessSlots(
   299	  dir: string,
   300	  now: number,
   301	  staleMs: number,
   302	  lockTiming: ProviderRegistryLockTiming = {},
   303	): ProviderProcessLiveDescriptor[] {
   304	  return withProviderRegistryLock(dir, () => scanLiveProviderProcessSlotsUnlocked(dir, now, staleMs), lockTiming);
