   307	export function acquireProviderProcessSlot(
   308	  dir: string,
   309	  cap: number,
   310	  staleMs: number,
   311	  now: number,
   312	  meta: ProviderProcessSlotMeta,
   313	  lockTiming: ProviderRegistryLockTiming = {},
   314	): AcquiredProviderProcessSlot | null {
   315	  mkdirSync(dir, { recursive: true });
   316	  const boundedCap = Number.isFinite(cap) && Number.isInteger(cap) && cap > 0
   317	    ? cap
   318	    : PROVIDER_PROCESS_MAX_CONCURRENT_DEFAULT;
   319	  return withProviderRegistryLock(dir, () => {
   320	    const live = scanLiveProviderProcessSlotsUnlocked(dir, now, staleMs);
   321	    if (live.length >= boundedCap) return null;
   322	    const token = randomUUID();
   323	    const record: ProviderProcessSlotFileMeta = { ...meta, token };
   324	    for (let index = 0; index < boundedCap; index += 1) {
   325	      const file = join(dir, `slot-${index}.json`);
   326	      if (writeProviderProcessSlotExclusive(file, record)) return { file, token };
   327	      const judged = readSlotOccupant(file);
   328	      if (!slotReclaimable(judged, file, now, staleMs)) continue;
   329	      if (judged.state !== 'missing') {
   330	        if (!sameSlotOccupant(readSlotOccupant(file), judged)) continue;
   331	        try { unlinkSync(file); } catch { /* exclusive recreate decides the winner */ }
   332	      }
   333	      if (writeProviderProcessSlotExclusive(file, record)) return { file, token };
   334	    }
   335	    return null;
   336	  }, lockTiming);
   337	}
