   339	export function releaseProviderProcessSlot(
   340	  file: string | null,
   341	  token: string | null,
   342	  lockTiming: ProviderRegistryLockTiming = {},
   343	  mutationOps: ProviderRegistryMutationOps = DEFAULT_PROVIDER_REGISTRY_MUTATION_OPS,
   344	): void {
   345	  if (!file || !token) return;
   346	  const dir = dirname(file);
   347	  withProviderRegistryLock(dir, () => {
   348	    const occupant = readSlotOccupant(file);
   349	    if (occupant.state !== 'valid' || occupant.token !== token) return;
   350	    mutationOps.unlink(file);
   351	  }, lockTiming);
   352	}
