   354	/**
   355	 * B-137a F-119: BEST-EFFORT release for `finally` blocks.
   356	 *
   357	 * Two correct-but-opposed requirements meet here:
   358	 *   1. A release failure must be OBSERVABLE, not a silent capacity leak --
   359	 *      releaseProviderProcessSlot therefore throws, and a registry smoke pins
   360	 *      that ("slot unlink mutation failure must be observable instead of
   361	 *      silently leaking capacity").
   362	 *   2. Every production release happens in a bare `finally` (host-run,
   363	 *      autopilot-executor, codex-review-leaf, provider-process-admission), and
   364	 *      a throw from `finally` REPLACES the in-flight exception -- hiding the
   365	 *      real provider failure -- or turns a successful run into a hard error.
   366	 *      host-run.ts's original releaseSlot wrapped its body in try/catch for
   367	 *      exactly this reason; a refactor dropped that.
   368	 *
   369	 * Swallowing inside the primitive would satisfy (2) by destroying (1). So the
   370	 * primitive keeps throwing and `finally` callers use this wrapper, which
   371	 * reports the failure through onFailure instead of hijacking control flow.
   372	 * Capacity is still reclaimable: pid-death detection and the orphan backstop
   373	 * recover a leaked slot, whereas a masked exception is unrecoverable.
   374	 */
   375	export function releaseProviderProcessSlotBestEffort(
   376	  file: string | null,
   377	  token: string | null,
   378	  onFailure: (error: unknown) => void = defaultReleaseFailureReporter,
   379	  lockTiming: ProviderRegistryLockTiming = {},
   380	  mutationOps: ProviderRegistryMutationOps = DEFAULT_PROVIDER_REGISTRY_MUTATION_OPS,
   381	): void {
   382	  try {
   383	    releaseProviderProcessSlot(file, token, lockTiming, mutationOps);
   384	  } catch (error) {
   385	    // Never rethrow: this runs in finally. Reporting must not fail either.
   386	    try {
   387	      onFailure(error);
   388	    } catch { /* a broken reporter must not mask the caller's exception */ }
   389	  }
   390	}
   391	
   392	function defaultReleaseFailureReporter(error: unknown): void {
   393	  const detail = error instanceof Error ? error.message : String(error);
   394	  process.stderr.write(
   395	    `⚠ provider process slot release failed (capacity is reclaimed by pid-death / orphan backstop): ${detail}\n`,
   396	  );
   397	}
