   399	export function transferProviderProcessSlotToProvider(
   400	  file: string | null,
   401	  token: string | null,
   402	  identity: {
   403	    pid: number;
   404	    pgid: number | null;
   405	    spawnedAt: string;
   406	    startFingerprint: string | null;
   407	    processGroupIsolated: boolean;
   408	  },
   409	  lockTiming: ProviderRegistryLockTiming = {},
   410	): boolean {
   411	  if (!file || !token) return false;
   412	  if (
   413	    !Number.isInteger(identity.pid) || identity.pid <= 0
   414	    || !identity.processGroupIsolated
   415	    || !Number.isInteger(identity.pgid) || (identity.pgid ?? 0) <= 0
   416	  ) return false;
   417	  const dir = dirname(file);
   418	  return withProviderRegistryLock(dir, () => {
   419	    const occupant = readSlotOccupant(file);
   420	    if (occupant.state !== 'valid' || occupant.token !== token) return false;
   421	    const next: ProviderProcessSlotFileMeta = {
   422	      ...(occupant.meta as unknown as ProviderProcessSlotFileMeta),
   423	      pid: identity.pid,
   424	      providerPid: identity.pid,
   425	      providerPgid: identity.pgid!,
   426	      providerSpawnedAt: identity.spawnedAt,
   427	      providerStartFingerprint: identity.startFingerprint ?? undefined,
   428	      providerProcessGroupIsolated: true,
   429	      token,
   430	    };
   431	    const temporary = `${file}.${token}.transfer`;
   432	    writeFileSync(temporary, JSON.stringify(next), { encoding: 'utf8', flag: 'wx', mode: 0o600 });
   433	    try {
   434	      // Registry lock + exact token check makes this replacement ownership-safe.
   435	      renameSync(temporary, file);
   436	    } finally {
   437	      try { unlinkSync(temporary); } catch { /* rename already consumed it */ }
   438	    }
   439	    return true;
   440	  }, lockTiming);
   441	}
